#if __riscv_vector
static inline void gemm_transB_vec(const Mat& A, const Mat& BT, const Mat& C, Mat& top_blob, float alpha, float beta, int broadcast_type_C, int output_transpose, const Option& opt)
{
    const int M = A.dims == 3 ? A.c : A.h;
    const int N = BT.dims == 3 ? BT.c : BT.h;
    const int K = A.w;

    const int out_hstep = top_blob.dims == 3 ? (int)top_blob.cstep : top_blob.w;

#pragma omp parallel for num_threads(opt.num_threads)
    for (int i = 0; i < M; i++)
    {
        const float* ptrA = (const float*)A + i * (A.dims == 3 ? (int)A.cstep : A.w);
        const float* ptrC = C;

        for (int j = 0; j < N; j++)
        {
            const float* ptrBT = (const float*)BT + j * (BT.dims == 3 ? (int)BT.cstep : BT.w);

            float sum_scalar = 0.f;
            if (ptrC)
            {
                if (broadcast_type_C == 0) sum_scalar = ptrC[0];
                if (broadcast_type_C == 1) sum_scalar = ptrC[i];
                if (broadcast_type_C == 2) sum_scalar = ptrC[i];
                if (broadcast_type_C == 3) sum_scalar = ptrC[i * N + j];
                if (broadcast_type_C == 4) sum_scalar = ptrC[j];
                sum_scalar *= beta;
            }

            size_t k_ofs = 0;
            vfloat32m8_t vacc = __riscv_vfmv_v_f_f32m8(0.f, __riscv_vsetvl_e32m8(K));
            while (k_ofs < (size_t)K)
            {
                size_t vl = __riscv_vsetvl_e32m8(K - k_ofs);
                vfloat32m8_t va = __riscv_vle32_v_f32m8(ptrA + k_ofs, vl);
                vfloat32m8_t vb = __riscv_vle32_v_f32m8(ptrBT + k_ofs, vl);
                // vacc += va * vb
                vacc = __riscv_vfmacc_vv_f32m8(vacc, va, vb, vl);
                k_ofs += vl;
            }
            vfloat32m1_t vzero = __riscv_vfmv_v_f_f32m1(0.f, __riscv_vsetvl_e32m1(1));
            vfloat32m1_t vred = __riscv_vfredusum_vs_f32m8_f32m1(vacc, vzero, __riscv_vsetvl_e32m8(1));
            float dot = __riscv_vfmv_f_s_f32m1_f32(vred);

            float sum = (sum_scalar + dot) * alpha;

            if (output_transpose)
                top_blob[j * out_hstep + i] = sum;
            else
                top_blob[i * out_hstep + j] = sum;
        }
    }
